import{z as t,x as i,o as E,c as A,q as c,j as s,D as d,d as e,s as r,S as n,b as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"调用约定与栈","description":"","frontmatter":{"title":"调用约定与栈","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/calling-convention-stack.md","filePath":"cs/calling-convention-stack.md","lastUpdated":1791413859000}'),B={name:"cs/calling-convention-stack.md"};function p(C,a,m,D,f,h){const l=i("Mermaid");return E(),A("div",null,[a[2]||(a[2]=c('<h1 id="调用约定与栈" tabindex="-1">调用约定与栈 <a class="header-anchor" href="#调用约定与栈" aria-label="Permalink to &quot;调用约定与栈&quot;">​</a></h1><div class="epigraph"><p>ISA 只保证 `jal` 把返回地址放进 `rd`；谁保存哪些寄存器、参数放哪、栈向哪长，是软件与硬件共同遵守的 ABI。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；RISC-V Calling Convention 整理</footer></div><p>上一课<a href="/cs/bus-mmio">总线与 MMIO</a>让硬件能执行任意指令序列。本课不重画 FSM 状态，也不从操作系统进程映像另起。缺口是：过程调用在 ISA 里只有 <code>jal</code>/<code>jalr</code> 与一堆通用寄存器。没有约定，调用者与被调用者会互相覆盖 <code>x</code> 寄存器，返回地址也会丢。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>RV32I 能跳、能存。缺口是 <strong>ABI</strong>：参数进 <code>a0</code>–<code>a7</code>（<code>x10</code>–<code>x17</code>），返回值 <code>a0</code>/<code>a1</code>；<code>ra</code> 存返回地址；栈由 <code>sp</code> 指向，向低地址增长；调用者保存与被调用者保存寄存器划分（caller/callee saved）。栈帧：保存 <code>ra</code>、<code>s</code> 寄存器、局部变量、溢出的参数。</p><p>硬件不强制这些，编译器与手写汇编必须一致。叶子函数可以不建帧，但不得破坏 callee-saved。</p><h3 id="栈不是「栈-adt-课」" tabindex="-1">栈不是「栈 ADT 课」 <a class="header-anchor" href="#栈不是「栈-adt-课」" aria-label="Permalink to &quot;栈不是「栈 ADT 课」&quot;">​</a></h3><p>这里的栈是内存中由 <code>sp</code> 界定的连续区，用 <code>sw</code>/<code>lw</code> 访问。数据结构课的栈抽象会后出现；本课是组成层的调用栈。不要把 Java 操作数栈或 x87 浮点栈混进来。</p><p><span class="marginnote">Patterson/Hennessy 用 RISC-V 调用例子画栈帧。官方 psABI 规定寄存器角色。本课不把完整 ELF 重定位提前。</span></p><p><span class="marginnote">直觉类比：caller-saved 寄存器像公用马克笔，你一转身就可能被别人拿走，想留着就先抄到自己的本子上（存栈）；callee-saved 寄存器像借来的书，谁想用都必须原样归还，跨调用放进去的东西还在。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>jal rd, offset</code> 写 <code>rd=PC+4</code> 并跳；惯例 <code>rd=ra</code>。被调用者：<code>addi sp,sp,-N</code>，存 <code>ra</code> 与需保存的 <code>s</code> 寄存器，用完 <code>lw</code> 恢复，<code>addi sp,sp,N</code>，<code>jalr x0,0(ra)</code>。递归每次新帧，否则 <code>ra</code> 被覆盖。</p>',12)),(E(),s(n,null,{default:d(()=>[r(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20JAL%5B%22jal%20%E5%86%99%20ra%22%5D%20--%3E%20FRAME%5B%22%E6%A0%88%E5%B8%A7%EF%BC%9Ara%20%E4%B8%8E%20s%20%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A%20%20FRAME%20--%3E%20BODY%5B%22%E8%BF%87%E7%A8%8B%E4%BD%93%22%5D%0A%20%20BODY%20--%3E%20RET%5B%22%E6%81%A2%E5%A4%8D%20sp%20%E4%B8%8E%20jalr%22%5D%0A%20%20RET%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%BC%82%E5%B8%B8%E4%B9%9F%E6%94%B9%20PC%22%5D%0A"})]),fallback:d(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("h2",{id:"机制",tabindex:"-1"},[e("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=o("p",null,[e("叶子过程可把 "),o("code",null,"ra"),e(" 留在寄存器。非叶子必须把 "),o("code",null,"ra"),e(" 入栈再 "),o("code",null,"jal"),e(" 出去。变长参数与栈上传参是 ABI 细节，本课点到：寄存器不够则放在 "),o("code",null,"sp"),e(" 之上的约定槽。栈溢出是软件错误，硬件只在访问未映射页时异常——页表很后。")],-1)),(E(),s(n,null,{default:d(()=>[r(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E8%BF%87%E7%A8%8B%E8%A2%AB%E8%B0%83%E7%94%A8%22%5D%20--%3E%20LEAF%7B%22%E8%BF%87%E7%A8%8B%E4%BD%93%E9%87%8C%E8%BF%98%E6%9C%89%20call%20%E5%90%97%EF%BC%9F%22%7D%0A%20%20LEAF%20--%3E%7C%22%E6%B2%A1%E6%9C%89%EF%BC%9A%E5%8F%B6%E5%AD%90%E8%BF%87%E7%A8%8B%22%7C%20KEEP%5B%22ra%20%E7%95%99%E5%9C%A8%E5%AF%84%E5%AD%98%E5%99%A8%EF%BC%8C%E5%8F%AF%E4%B8%8D%E5%BB%BA%E5%B8%A7%22%5D%0A%20%20LEAF%20--%3E%7C%22%E6%9C%89%EF%BC%9A%E9%9D%9E%E5%8F%B6%E5%AD%90%E8%BF%87%E7%A8%8B%22%7C%20PUSH%5B%22%E5%85%88%20addi%20sp%2Csp%2C-N%20%E6%8A%8A%20ra%20%E5%85%A5%E6%A0%88%22%5D%0A%20%20PUSH%20--%3E%20SUB%5B%22jal%20%E5%87%BA%E5%8E%BB%EF%BC%8C%E5%AD%90%E8%B0%83%E7%94%A8%E8%A6%86%E7%9B%96%20ra%20%E4%B9%9F%E6%97%A0%E5%A6%A8%22%5D%0A%20%20SUB%20--%3E%20BACK%5B%22%E8%BF%94%E5%9B%9E%E5%90%8E%E4%BB%8E%E6%A0%88%E9%87%8C%E6%81%A2%E5%A4%8D%20ra%22%5D%0A%20%20KEEP%20--%3E%20RET%5B%22ret%20%E5%9B%9E%E8%B0%83%E7%94%A8%E6%96%B9%22%5D%0A%20%20BACK%20--%3E%20RET%0A"})]),fallback:d(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=c('<p><span class="marginnote">数字实例：<code>addi sp,sp,-32</code> 把栈指针从 0x7fff_f000 减到 0x7fff_efe0，向下开出 32 字节的新帧；返回前 <code>addi sp,sp,32</code> 加回去。两次之间的所有保存与恢复都发生在这个窗口里，栈向低地址长。</span></p><p><span class="marginnote">常见误区：初学者容易以为栈溢出会被硬件立刻拦下，实际上硬件只在访问未映射页时才异常；若栈悄悄写进别的数据区，程序会带着被覆盖的返回地址继续跑，崩在一个看似毫无关系的地方。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲异常帧、不讲信号处理器。不把线程的多栈、协程提前。尾调用优化可省略帧，但是约定下的优化，不是硬件指令。</p><p>后课默认：过程调用遵守 RISC-V 整数 ABI；栈向低地址长。异常与中断也会改 PC，但不是 <code>jal</code>，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li><code>jal</code> 只提供返回地址机制；ABI 规定寄存器与栈帧。</li><li>caller/callee saved 防止互相覆盖。</li><li>递归必须入栈 <code>ra</code>。异常入口是另一条改 PC 的路。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；RISC-V psABI。</li></ul>',7))])}const _=t(B,[["render",p]]);export{F as __pageData,_ as default};
